<?php if ( $onboarding ) : ?><div class="rv-member-notice"><strong>حساب شما ساخته شد.</strong><p>نام و تصویرتان را تکمیل کنید تا دیگران شما را بهتر بشناسند. تکمیل پروفایل شرط رأی دادن نیست.</p></div><?php endif; ?>
<form class="rv-member-card rv-member-form" data-rv-form data-dirty-guard enctype="multipart/form-data" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="revayat_member_profile"><?php wp_nonce_field( 'rv_member_profile', 'rv_nonce' ); ?><input type="hidden" name="version" value="<?php echo esc_attr( $profile['version'] ); ?>"><input type="hidden" name="onboarding" value="<?php echo $onboarding ? '1' : '0'; ?>">
